import{_ as a,a0 as d,w as n,s as p,ao as r,I as i,x as e,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"高級 SSH 速查表 | LCTT x X-CMD","titleTemplate":false,"description":"高級 SSH 速查表 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"高級 SSH 速查表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"高級 SSH 速查表 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180402 Advanced SSH Cheat Sheet","title":"高級 SSH 速查表","tag":"201804","desc":""},"relativePath":"201804/20180402 Advanced SSH Cheat Sheet.md","filePath":"[post].md"}'),g={name:"201804/20180402 Advanced SSH Cheat Sheet.md"};function c(h,t,k,u,f,b){const s=d("Link");return n(),p("div",null,[t[13]||(t[13]=r(`<h1 id="高級-ssh-速查表" tabindex="-1">高級 SSH 速查表 <a class="header-anchor" href="#高級-ssh-速查表" aria-label="Permalink to “高級 SSH 速查表”">​</a></h1><p>所有人都知道 SSH 是一種遠程登錄工具，然而它也有許多其他用途。</p><p>創建一個 SOCKS 代理來瀏覽網頁（也就是翻牆啦）：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -D &lt;port&gt; &lt;remote_host&gt;</span></span></code></pre></div><p>設置 <code>localhost:&lt;port&gt;</code> 作為你瀏覽器的代理</p></blockquote><p>連接一個堡壘機後的 Windows RDP 主機：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -L &lt;port&gt;:&lt;target_host&gt;:3389 &lt;bastion_server&gt;</span></span></code></pre></div><p>讓你的 RDP 客户端連接到 <code>localhost:&lt;port&gt;</code></p></blockquote><p>在不使用 VNC 端口的情況下，連接遠程 VNC 主機：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -L 5901:localhost:5901 &lt;remote_host&gt;</span></span></code></pre></div><p>讓你的 VNC 客户端連接到 <code>localhost:5901</code></p></blockquote><p>按照這個思路，你可以映射任意端口：LDAP (389)、631 (CUPS)、8080 (替代的 HTTP)，等等。</p><p>產生一個新的 SSH 密鑰對：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen</span></span></code></pre></div></blockquote><p>更新密鑰對的密碼：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen -p</span></span></code></pre></div></blockquote><p>把公鑰複製到遠程主機上：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-copy-id -i &lt;identity file&gt; &lt;remote_host&gt;</span></span></code></pre></div></blockquote><p>SSH 有一堆命令列選項，但是如果有一些是你經常使用的，你可以為它們在 SSH 配置文件 (\${HOME}/.ssh/config) 裏創建一個入口。比如：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host myhouse </span></span>
<span class="line"><span>   User itsme </span></span>
<span class="line"><span>   HostName house.example.com</span></span></code></pre></div></blockquote><p>那麼你就可以輸入 <code>ssh myhouse</code> 來代替 <code>ssh itsme@house.example.com</code>。</p><p>以下是常用的命令列選項和他們的配置文件寫法。一些是常用的簡化寫法。請查看 <code>ssh(1)</code> 和 <code>ssh_config(5)</code> 的手冊頁來獲取詳盡信息。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令列</th><th style="text-align:left;">配置文件</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-l &lt;login name&gt;</code></td><td style="text-align:left;"><code>User &lt;login name&gt;</code></td><td style="text-align:left;">遠程主機的登錄用户名。</td></tr><tr><td style="text-align:left;"><code>-i &lt;identity file&gt;</code></td><td style="text-align:left;"><code>IdentityFile &lt;identity file&gt;</code></td><td style="text-align:left;">指定要使用的鑑權文件（SSH 密碼對）。</td></tr><tr><td style="text-align:left;"><code>-p &lt;remote port&gt;</code></td><td style="text-align:left;"><code>Port &lt;remote port&gt;</code></td><td style="text-align:left;">遠程 SSH 守護進程監聽的端口號。 (默認為 22)</td></tr><tr><td style="text-align:left;"><code>-C</code></td><td style="text-align:left;"><code>Compression &lt;yes,no&gt;</code></td><td style="text-align:left;">壓縮往來信息。 (默認為 no)</td></tr><tr><td style="text-align:left;"><code>-D &lt;port&gt;</code></td><td style="text-align:left;"><code>DynamicForward &lt;port&gt;</code></td><td style="text-align:left;">把本地端口的報文轉發到遠程主機。</td></tr><tr><td style="text-align:left;"><code>-X</code></td><td style="text-align:left;"><code>ForwardX11 &lt;yes,no&gt;</code></td><td style="text-align:left;">把 X11 的圖像數據轉發到遠程主機的端口. (默認為 no)</td></tr><tr><td style="text-align:left;"><code>-A</code></td><td style="text-align:left;"><code>ForwardAgent &lt;yes,no&gt;</code></td><td style="text-align:left;">把授權代理的報文轉發給遠程主機。如果你使用第三方主機登錄，這個功能將很有用。 (默認為 no)</td></tr><tr><td style="text-align:left;"><code>-4</code>（僅使用 IPv4） <code>-6</code> （僅使用 IPv6）</td><td style="text-align:left;"><code>AddressFamily &lt;any,inet4,inet6&gt;</code></td><td style="text-align:left;">指定僅使用 IPv4 或者 IPv6。</td></tr><tr><td style="text-align:left;"><code>-L &lt;local port&gt;:&lt;target host&gt;:&lt;target port&gt;</code></td><td style="text-align:left;"><code>LocalForward &lt;local port&gt;:&lt;target host&gt;:&lt;target port&gt;</code></td><td style="text-align:left;">把本地主機指定端口的報文轉發到遠程主機的某個端口。</td></tr></tbody></table></div><p>opensource.com Twitter @opensourceway | facebook.com/opensourceway | IRC: #opensource.com on Freenode</p><hr><p>作者簡介：</p><p>Ben Cotton 是業餘的氣象學家和職業的高性能計算工程師。Ben 是微軟 Azure 的產品營銷經理，專注於高性能計算。他是一個 Fedora 用户和貢獻者，共同創立了一個當地的開放源碼羣，並且是開源促進會的成員和保護自由軟件的支持者。通過以下方式聯繫他 Twitter (@FunnelFiasco) 或者 FunnelFiasco.com.</p><hr>`,25)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),l(s,{href:"https://opensource.com/sites/default/files/gated-content/cheat_sheet_ssh_v03.pdf"},{default:o(()=>[...t[0]||(t[0]=[e("https://opensource.com/sites/default/files/gated-content/cheat_sheet_ssh_v03.pdf",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),l(s,{href:"https://opensource.com/users/bcotton"},{default:o(()=>[...t[2]||(t[2]=[e("BEN COTTON",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),l(s,{href:"https://github.com/kennethXia"},{default:o(()=>[...t[3]||(t[3]=[e("kennethXia",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),l(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const S=a(g,[["render",c]]);export{x as __pageData,S as default};
